using System.Text;
using System.Text.Encodings.Web;
using System.Text.Json;
using System.Text.Json.Serialization;

namespace BatchRenameStudio.Core;

/// <summary>
/// Known operation identifiers. Kept as plain strings because the on-disk
/// contract is a string and unknown values must be reported, not silently mapped.
/// </summary>
public static class Ops
{
    public const string Replace = "replace";
    public const string Insert = "insert";
    public const string Remove = "remove";
    public const string Sequence = "sequence";
    public const string Case = "case";
    public const string Extension = "extension";

    public static readonly string[] All = { Replace, Insert, Remove, Sequence, Case, Extension };
}

/// <summary>
/// One step of a rule set. This is a direct mirror of the JSON contract: every
/// operation shares one carrier type so that load / edit / save round-trips
/// without a discriminated-union mapping layer.
/// </summary>
public sealed class RuleStep
{
    [JsonPropertyName("op")] public string Op { get; set; } = Ops.Replace;

    // replace
    [JsonPropertyName("find")] public string? Find { get; set; }
    [JsonPropertyName("replaceWith")] public string? ReplaceWith { get; set; }
    [JsonPropertyName("regex")] public bool? Regex { get; set; }
    [JsonPropertyName("ignoreCase")] public bool? IgnoreCase { get; set; }

    // insert
    [JsonPropertyName("text")] public string? Text { get; set; }
    [JsonPropertyName("position")] public string? Position { get; set; }
    [JsonPropertyName("index")] public int? Index { get; set; }

    // remove
    [JsonPropertyName("from")] public int? From { get; set; }
    [JsonPropertyName("count")] public int? Count { get; set; }

    // sequence
    [JsonPropertyName("pattern")] public string? Pattern { get; set; }
    [JsonPropertyName("start")] public int? Start { get; set; }
    [JsonPropertyName("step")] public int? Step { get; set; }

    // case / extension
    [JsonPropertyName("mode")] public string? Mode { get; set; }

    // extension
    [JsonPropertyName("value")] public string? Value { get; set; }

    public RuleStep Clone() => (RuleStep)MemberwiseClone();

    /// <summary>Human readable one-line summary, used by the rule list in the GUI.</summary>
    public string Describe()
    {
        switch (Op)
        {
            case Ops.Replace:
                var flags = new List<string>();
                if (Regex == true) flags.Add("regex");
                if (IgnoreCase == true) flags.Add("忽略大小寫");
                var suffix = flags.Count > 0 ? "  [" + string.Join(", ", flags) + "]" : "";
                return $"取代：「{Find}」→「{ReplaceWith}」{suffix}";
            case Ops.Insert:
                return Position == "index"
                    ? $"插入：「{Text}」於位置 {Index ?? 0}"
                    : $"插入：「{Text}」於{(Position == "suffix" ? "結尾" : "開頭")}";
            case Ops.Remove:
                return $"移除：自位置 {From ?? 0} 起 {Count ?? 0} 個字元";
            case Ops.Sequence:
                return $"編號：「{Pattern}」起始 {Start ?? 1} 遞增 {Step ?? 1}（{(Position == "suffix" ? "結尾" : "開頭")}）";
            case Ops.Case:
                return $"大小寫：{Mode switch { "upper" => "全大寫", "lower" => "全小寫", "title" => "字首大寫", _ => Mode }}";
            case Ops.Extension:
                return Mode == "set"
                    ? $"副檔名：設為「{Value}」"
                    : $"副檔名：{(Mode == "upper" ? "轉大寫" : "轉小寫")}";
            default:
                return $"（未知操作：{Op}）";
        }
    }
}

/// <summary>A complete rule set — the contents of rules.json.</summary>
public sealed class RuleSet
{
    [JsonPropertyName("applyTo")] public string ApplyTo { get; set; } = ApplyTargets.Name;
    [JsonPropertyName("sort")] public string Sort { get; set; } = SortModes.Name;
    [JsonPropertyName("steps")] public List<RuleStep> Steps { get; set; } = new();

    private static readonly JsonSerializerOptions ReadOptions = new()
    {
        PropertyNameCaseInsensitive = true,
        AllowTrailingCommas = true,
        ReadCommentHandling = JsonCommentHandling.Skip,
        NumberHandling = JsonNumberHandling.AllowReadingFromString,
    };

    private static readonly JsonSerializerOptions WriteOptions = new()
    {
        WriteIndented = true,
        DefaultIgnoreCondition = JsonIgnoreCondition.WhenWritingNull,
        Encoder = JavaScriptEncoder.UnsafeRelaxedJsonEscaping,
    };

    public static RuleSet Load(string path)
    {
        var json = File.ReadAllText(path, Encoding.UTF8);
        return Parse(json);
    }

    public static RuleSet Parse(string json)
    {
        RuleSet? set;
        try
        {
            set = JsonSerializer.Deserialize<RuleSet>(json, ReadOptions);
        }
        catch (JsonException ex)
        {
            throw new RuleSetException("rules.json 不是合法的 JSON：" + ex.Message, ex);
        }

        if (set is null) throw new RuleSetException("rules.json 內容為空。");

        set.ApplyTo = string.IsNullOrWhiteSpace(set.ApplyTo) ? ApplyTargets.Name : set.ApplyTo.Trim();
        set.Sort = string.IsNullOrWhiteSpace(set.Sort) ? SortModes.Name : set.Sort.Trim();
        set.Steps ??= new List<RuleStep>();
        set.Validate();
        return set;
    }

    public string ToJson() => JsonSerializer.Serialize(this, WriteOptions);

    public void Save(string path)
    {
        var dir = Path.GetDirectoryName(Path.GetFullPath(path));
        if (!string.IsNullOrEmpty(dir)) Directory.CreateDirectory(dir);
        File.WriteAllText(path, ToJson(), Utf8.NoBom);
    }

    public RuleSet Clone() => new()
    {
        ApplyTo = ApplyTo,
        Sort = Sort,
        Steps = Steps.Select(s => s.Clone()).ToList(),
    };

    /// <summary>
    /// Fail fast on anything the engine cannot execute deterministically.
    /// A rule set that is silently half-applied is worse than a hard error.
    /// </summary>
    public void Validate()
    {
        if (!ApplyTargets.IsValid(ApplyTo))
            throw new RuleSetException($"applyTo 只能是 \"name\" 或 \"nameAndExtension\"，收到 \"{ApplyTo}\"。");
        if (!SortModes.IsValid(Sort))
            throw new RuleSetException($"sort 只能是 \"name\"、\"created\" 或 \"modified\"，收到 \"{Sort}\"。");

        for (var i = 0; i < Steps.Count; i++)
        {
            var s = Steps[i];
            var where = $"steps[{i}]";
            switch (s.Op)
            {
                case Ops.Replace:
                    if (s.Regex == true)
                    {
                        try
                        {
                            _ = TextOps.BuildRegex(s.Find ?? "", s.IgnoreCase == true);
                        }
                        catch (ArgumentException ex)
                        {
                            throw new RuleSetException($"{where}: regex 語法錯誤 — {ex.Message}");
                        }
                    }
                    break;
                case Ops.Insert:
                    if (s.Position is not null && s.Position is not ("prefix" or "suffix" or "index"))
                        throw new RuleSetException($"{where}: position 只能是 \"prefix\"、\"suffix\" 或 \"index\"。");
                    break;
                case Ops.Sequence:
                    if (s.Position is not null && s.Position is not ("prefix" or "suffix"))
                        throw new RuleSetException($"{where}: position 只能是 \"prefix\" 或 \"suffix\"。");
                    break;
                case Ops.Case:
                    if (s.Mode is not ("upper" or "lower" or "title"))
                        throw new RuleSetException($"{where}: mode 只能是 \"upper\"、\"lower\" 或 \"title\"。");
                    break;
                case Ops.Extension:
                    if (s.Mode is not ("lower" or "upper" or "set"))
                        throw new RuleSetException($"{where}: mode 只能是 \"lower\"、\"upper\" 或 \"set\"。");
                    break;
                case Ops.Remove:
                    break;
                default:
                    throw new RuleSetException($"{where}: 未知的 op \"{s.Op}\"。可用：{string.Join(", ", Ops.All)}。");
            }
        }
    }
}

public static class ApplyTargets
{
    public const string Name = "name";
    public const string NameAndExtension = "nameAndExtension";
    public static bool IsValid(string v) => v is Name or NameAndExtension;
}

public static class SortModes
{
    public const string Name = "name";
    public const string Created = "created";
    public const string Modified = "modified";
    public static bool IsValid(string v) => v is Name or Created or Modified;
}

public sealed class RuleSetException : Exception
{
    public RuleSetException(string message, Exception? inner = null) : base(message, inner) { }
}

/// <summary>Single source of truth for the "UTF-8 without BOM" output contract.</summary>
public static class Utf8
{
    public static readonly UTF8Encoding NoBom = new(encoderShouldEmitUTF8Identifier: false, throwOnInvalidBytes: false);
}

