using System.Text.Encodings.Web;
using System.Text.Json;
using System.Text.Json.Serialization;

namespace BatchRenameStudio.Core;

public static class PlanStatus
{
    public const string Ok = "ok";
    public const string Collision = "collision";
    public const string Unchanged = "unchanged";
    public const string Invalid = "invalid";
}

/// <summary>One row of plan.json. Property order here IS the serialized order.</summary>
public sealed class PlanItem
{
    [JsonPropertyName("original")] public string Original { get; set; } = "";
    [JsonPropertyName("proposed")] public string Proposed { get; set; } = "";
    [JsonPropertyName("status")] public string Status { get; set; } = PlanStatus.Ok;
    [JsonPropertyName("reason")] public string Reason { get; set; } = "";

    /// <summary>Absolute source path. Not part of the output contract, so it is not serialized.</summary>
    [JsonIgnore] public string SourcePath { get; set; } = "";

    /// <summary>Counter value assigned by sequence steps; shown in the GUI, never serialized.</summary>
    [JsonIgnore] public int Ordinal { get; set; }
}

public sealed class PlanSummary
{
    [JsonPropertyName("total")] public int Total { get; set; }
    [JsonPropertyName("ok")] public int Ok { get; set; }
    [JsonPropertyName("collision")] public int Collision { get; set; }
    [JsonPropertyName("unchanged")] public int Unchanged { get; set; }
    [JsonPropertyName("invalid")] public int Invalid { get; set; }

    public override string ToString() =>
        $"total={Total} ok={Ok} collision={Collision} unchanged={Unchanged} invalid={Invalid}";
}

/// <summary>The whole plan.json document.</summary>
public sealed class PlanDocument
{
    public const int CurrentSchemaVersion = 1;

    [JsonPropertyName("schemaVersion")] public int SchemaVersion { get; set; } = CurrentSchemaVersion;
    [JsonPropertyName("items")] public List<PlanItem> Items { get; set; } = new();
    [JsonPropertyName("summary")] public PlanSummary Summary { get; set; } = new();

    /// <summary>
    /// Fixed options: no reordering, no culture-dependent formatting, relaxed encoder so that
    /// non-ASCII file names stay readable. Deterministic byte-for-byte (contract rule 15).
    /// </summary>
    private static readonly JsonSerializerOptions Options = new()
    {
        WriteIndented = true,
        Encoder = JavaScriptEncoder.UnsafeRelaxedJsonEscaping,
    };

    public string ToJson() => JsonSerializer.Serialize(this, Options);

    /// <summary>Writes plan.json as UTF-8 without a BOM, creating the parent directory if needed.</summary>
    public void Save(string path)
    {
        var full = Path.GetFullPath(path);
        var dir = Path.GetDirectoryName(full);
        if (!string.IsNullOrEmpty(dir)) Directory.CreateDirectory(dir);
        File.WriteAllText(full, ToJson(), Utf8.NoBom);
    }

    public void RecomputeSummary()
    {
        Summary = new PlanSummary
        {
            Total = Items.Count,
            Ok = Items.Count(i => i.Status == PlanStatus.Ok),
            Collision = Items.Count(i => i.Status == PlanStatus.Collision),
            Unchanged = Items.Count(i => i.Status == PlanStatus.Unchanged),
            Invalid = Items.Count(i => i.Status == PlanStatus.Invalid),
        };
    }
}

