namespace BatchRenameStudio.Core;

/// <summary>One source file as seen by the engine. Kept separate from FileInfo so the
/// engine can be exercised without touching a real directory.</summary>
public sealed class SourceFile
{
    public required string Name { get; init; }
    public required string FullPath { get; init; }
    public DateTime CreatedUtc { get; init; }
    public DateTime ModifiedUtc { get; init; }
}

/// <summary>
/// The planning engine. Implements contract rules 1-15 literally; every branch below
/// is annotated with the rule number it realises.
/// </summary>
public static class RenameEngine
{
    /// <summary>Rule 1: regular files directly inside the folder, non-recursive, no directories.</summary>
    public static List<SourceFile> Scan(string directory)
    {
        var di = new DirectoryInfo(directory);
        if (!di.Exists) throw new DirectoryNotFoundException($"找不到資料夾：{directory}");

        var result = new List<SourceFile>();
        foreach (var fi in di.EnumerateFiles("*", SearchOption.TopDirectoryOnly))
        {
            DateTime created, modified;
            try
            {
                created = fi.CreationTimeUtc;
                modified = fi.LastWriteTimeUtc;
            }
            catch (IOException)
            {
                created = modified = DateTime.MinValue;
            }

            result.Add(new SourceFile
            {
                Name = fi.Name,
                FullPath = fi.FullName,
                CreatedUtc = created,
                ModifiedUtc = modified,
            });
        }
        return result;
    }

    /// <summary>Rule 5 / 14: processing order, which is also the order of plan items.</summary>
    public static List<SourceFile> SortFiles(IEnumerable<SourceFile> files, string sortMode)
    {
        var list = files.ToList();
        Comparison<SourceFile> cmp = sortMode switch
        {
            SortModes.Created => (a, b) =>
            {
                var c = a.CreatedUtc.CompareTo(b.CreatedUtc);
                return c != 0 ? c : string.CompareOrdinal(a.Name, b.Name);
            }
            ,
            SortModes.Modified => (a, b) =>
            {
                var c = a.ModifiedUtc.CompareTo(b.ModifiedUtc);
                return c != 0 ? c : string.CompareOrdinal(a.Name, b.Name);
            }
            ,
            // "name": ordinal (codepoint) ascending, case-sensitive.
            _ => (a, b) => string.CompareOrdinal(a.Name, b.Name),
        };
        list.Sort(cmp);
        return list;
    }

    public static PlanDocument Plan(string directory, RuleSet rules)
        => Plan(Scan(directory), rules);

    public static PlanDocument Plan(IEnumerable<SourceFile> files, RuleSet rules)
    {
        rules.Validate();

        var ordered = SortFiles(files, rules.Sort);
        var doc = new PlanDocument();

        // ---- pass 1: propose a name for every file, in processing order (rules 3-12) ----
        for (var i = 0; i < ordered.Count; i++)
        {
            var f = ordered[i];
            var proposed = Transform(f.Name, rules, i);
            doc.Items.Add(new PlanItem
            {
                Original = f.Name,
                Proposed = proposed,
                SourcePath = f.FullPath,
                Ordinal = i,
            });
        }

        // ---- pass 2: classify (rule 13) ----
        // Case-insensitive tallies, because Windows file names collide case-insensitively.
        var existing = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
        foreach (var f in ordered)
        {
            existing.TryGetValue(f.Name, out var n);
            existing[f.Name] = n + 1;
        }

        var proposedCounts = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
        foreach (var item in doc.Items)
        {
            proposedCounts.TryGetValue(item.Proposed, out var n);
            proposedCounts[item.Proposed] = n + 1;
        }

        foreach (var item in doc.Items)
        {
            var invalidity = NameRules.Invalidity(item.Proposed);
            if (invalidity is not null)
            {
                item.Status = PlanStatus.Invalid;
                item.Reason = invalidity;
                continue;
            }

            existing.TryGetValue(item.Proposed, out var existingCount);
            // Subtract this item's own contribution to the existing-name tally.
            if (string.Equals(item.Original, item.Proposed, StringComparison.OrdinalIgnoreCase))
                existingCount--;

            if (existingCount > 0)
            {
                item.Status = PlanStatus.Collision;
                item.Reason = "與資料夾中既有檔案同名";
                continue;
            }

            if (proposedCounts.TryGetValue(item.Proposed, out var dupes) && dupes > 1)
            {
                item.Status = PlanStatus.Collision;
                item.Reason = "與其他項目的新名稱重複";
                continue;
            }

            if (string.Equals(item.Original, item.Proposed, StringComparison.Ordinal))
            {
                item.Status = PlanStatus.Unchanged;
                item.Reason = "";
                continue;
            }

            item.Status = PlanStatus.Ok;
            item.Reason = "";
        }

        doc.RecomputeSummary();
        return doc;
    }

    /// <summary>
    /// Rules 3, 4, 6-12: run every step over the target string for one file.
    /// <paramref name="index"/> is the 0-based position in processing order and drives
    /// sequence numbering (rule 9) — it advances for every file regardless of status.
    /// </summary>
    public static string Transform(string originalName, RuleSet rules, int index)
    {
        if (rules.ApplyTo == ApplyTargets.NameAndExtension)
        {
            // Rule 3 / 12: the target string IS the whole (proposed) file name.
            var s = originalName;
            foreach (var step in rules.Steps)
            {
                if (step.Op == Ops.Extension)
                {
                    // Rule 11 + 12: an extension step re-splits the current string and
                    // rewrites its trailing extension.
                    var parts = NameRules.Split(s);
                    s = new NameParts(parts.Base, ApplyExtension(parts.Ext, step)).Combine();
                }
                else
                {
                    s = ApplyStringStep(s, step, index);
                }
            }
            return s;
        }
        else
        {
            // Rule 3: steps operate on the base; the extension is carried alongside and
            // only an `extension` step may touch it (rule 11).
            var parts = NameRules.Split(originalName);
            var baseName = parts.Base;
            var ext = parts.Ext;

            foreach (var step in rules.Steps)
            {
                if (step.Op == Ops.Extension) ext = ApplyExtension(ext, step);
                else baseName = ApplyStringStep(baseName, step, index);
            }

            return new NameParts(baseName, ext).Combine();
        }
    }

    private static string ApplyStringStep(string s, RuleStep step, int index)
    {
        switch (step.Op)
        {
            case Ops.Replace: // rule 6
                return TextOps.Replace(s, step.Find ?? "", step.ReplaceWith ?? "",
                                       step.Regex == true, step.IgnoreCase == true);

            case Ops.Insert: // rule 7
                return TextOps.Insert(s, step.Text ?? "", step.Position, step.Index ?? 0);

            case Ops.Remove: // rule 8
                return TextOps.Remove(s, step.From ?? 0, step.Count ?? 0);

            case Ops.Sequence: // rule 9
            {
                var start = step.Start ?? 1;
                var stride = step.Step ?? 1;
                var value = (long)start + (long)stride * index;
                var rendered = TextOps.RenderSequence(step.Pattern ?? "", value);
                return step.Position == "suffix" ? s + rendered : rendered + s;
            }

            case Ops.Case: // rule 10
                return step.Mode switch
                {
                    "upper" => s.ToUpperInvariant(),
                    "lower" => s.ToLowerInvariant(),
                    "title" => TextOps.ToTitleCase(s),
                    _ => s,
                };

            default:
                return s;
        }
    }

    /// <summary>Rule 11: always operates on the extension, which never includes the dot.</summary>
    private static string ApplyExtension(string ext, RuleStep step) => step.Mode switch
    {
        "lower" => ext.ToLowerInvariant(),
        "upper" => ext.ToUpperInvariant(),
        "set" => step.Value ?? "",
        _ => ext,
    };
}

