using System.Text;
using System.Text.RegularExpressions;

namespace BatchRenameStudio.Core;

/// <summary>The base / extension split of a file name. <see cref="Ext"/> never contains the dot.</summary>
public readonly record struct NameParts(string Base, string Ext)
{
    /// <summary>Reassembly per contract rule 12.</summary>
    public string Combine() => Ext.Length > 0 ? Base + "." + Ext : Base;
}

/// <summary>
/// Pure name-level rules from the contract: the split (rule 2), reassembly (rule 12)
/// and the validity test (rule 13, first bullet).
/// </summary>
public static class NameRules
{
    /// <summary>Characters Windows forbids in a file name, per contract rule 13.</summary>
    public static readonly char[] InvalidChars = { '<', '>', ':', '"', '/', '\\', '|', '?', '*' };

    public const int MaxNameLength = 255;

    private static readonly HashSet<string> ReservedNames = new(StringComparer.OrdinalIgnoreCase)
    {
        "CON", "PRN", "AUX", "NUL",
        "COM1", "COM2", "COM3", "COM4", "COM5", "COM6", "COM7", "COM8", "COM9",
        "LPT1", "LPT2", "LPT3", "LPT4", "LPT5", "LPT6", "LPT7", "LPT8", "LPT9",
    };

    /// <summary>
    /// Contract rule 2. dot = index of the LAST '.'; when dot &gt; 0 the name splits there
    /// and the extension excludes the dot. Otherwise the whole name is the base.
    /// </summary>
    public static NameParts Split(string name)
    {
        var dot = name.LastIndexOf('.');
        if (dot > 0) return new NameParts(name[..dot], name[(dot + 1)..]);
        return new NameParts(name, string.Empty);
    }

    /// <summary>
    /// Contract rule 13, first bullet. Returns null when the name is acceptable,
    /// otherwise a short human reason.
    /// </summary>
    public static string? Invalidity(string name)
    {
        if (name.Length == 0) return "名稱為空";
        if (name.Length > MaxNameLength) return $"名稱長度 {name.Length} 超過 {MaxNameLength}";

        foreach (var c in name)
        {
            if (c < ' ') return $"含控制字元 U+{(int)c:X4}";
            if (Array.IndexOf(InvalidChars, c) >= 0) return $"含不允許的字元 '{c}'";
        }

        var baseName = Split(name).Base;
        if (ReservedNames.Contains(baseName)) return $"「{baseName}」是 Windows 保留裝置名稱";

        return null;
    }

    public static bool IsReservedDeviceName(string baseName) => ReservedNames.Contains(baseName);
}

/// <summary>String transforms shared by the engine and the GUI preview.</summary>
public static class TextOps
{
    private static readonly TimeSpan RegexTimeout = TimeSpan.FromSeconds(2);

    /// <summary>Matches the single {n:PAD} token of a sequence pattern (rule 9).</summary>
    private static readonly Regex SequenceToken =
        new(@"\{n:(0+)\}", RegexOptions.CultureInvariant, RegexTimeout);

    public static Regex BuildRegex(string pattern, bool ignoreCase)
    {
        var options = RegexOptions.CultureInvariant;
        if (ignoreCase) options |= RegexOptions.IgnoreCase;
        return new Regex(pattern, options, RegexTimeout);
    }

    /// <summary>
    /// Contract rule 10, "title": for each maximal run of Unicode letters, uppercase the
    /// first character and lowercase the rest. Invariant culture keeps this deterministic
    /// across machine locales (see docs/DECISIONS.md, D-06).
    /// </summary>
    public static string ToTitleCase(string s)
    {
        var sb = new StringBuilder(s.Length);
        var inRun = false;
        foreach (var c in s)
        {
            if (char.IsLetter(c))
            {
                sb.Append(inRun ? char.ToLowerInvariant(c) : char.ToUpperInvariant(c));
                inRun = true;
            }
            else
            {
                sb.Append(c);
                inRun = false;
            }
        }
        return sb.ToString();
    }

    /// <summary>
    /// Renders a sequence pattern (rule 9) for one counter value. A pattern without the
    /// {n:PAD} token is emitted verbatim (see docs/DECISIONS.md, D-07).
    /// </summary>
    public static string RenderSequence(string pattern, int value)
    {
        if (string.IsNullOrEmpty(pattern)) return string.Empty;
        return SequenceToken.Replace(pattern, m =>
        {
            var width = m.Groups[1].Value.Length;
            return value.ToString(new string('0', width), System.Globalization.CultureInfo.InvariantCulture);
        }, count: 1);
    }

    public static string Insert(string s, string text, string? position, int index)
    {
        switch (position)
        {
            case "suffix":
                return s + text;
            case "index":
                var at = Math.Clamp(index, 0, s.Length);
                return s.Insert(at, text);
            default: // "prefix" and any unspecified value
                return text + s;
        }
    }

    /// <summary>Contract rule 8: from is clamped to [0, length], count to what remains.</summary>
    public static string Remove(string s, int from, int count)
    {
        var start = Math.Clamp(from, 0, s.Length);
        var take = Math.Clamp(count, 0, s.Length - start);
        return take == 0 ? s : s.Remove(start, take);
    }

    public static string Replace(string s, string find, string replaceWith, bool regex, bool ignoreCase)
    {
        if (regex)
        {
            return BuildRegex(find, ignoreCase).Replace(s, replaceWith);
        }

        // string.Replace throws on an empty needle; an empty literal find is a no-op.
        if (find.Length == 0) return s;
        return s.Replace(find, replaceWith, ignoreCase ? StringComparison.OrdinalIgnoreCase : StringComparison.Ordinal);
    }
}

