using System.Text.Json.Serialization;

namespace BatchRenameStudio.Core;

/// <summary>A single completed move, expressed as full paths so undo needs no context.</summary>
public sealed class RenameOperation
{
    [JsonPropertyName("from")] public string From { get; set; } = "";
    [JsonPropertyName("to")] public string To { get; set; } = "";
}

/// <summary>One applied batch — the unit of undo.</summary>
public sealed class RenameBatch
{
    [JsonPropertyName("directory")] public string Directory { get; set; } = "";
    [JsonPropertyName("appliedAtUtc")] public DateTime AppliedAtUtc { get; set; } = DateTime.UtcNow;
    [JsonPropertyName("operations")] public List<RenameOperation> Operations { get; set; } = new();

    private static readonly JsonSerializerOptions Options = new()
    {
        WriteIndented = true,
        Encoder = JavaScriptEncoder.UnsafeRelaxedJsonEscaping,
    };

    public string ToJson() => JsonSerializer.Serialize(this, Options);
}

public sealed class RenameResult
{
    public int Succeeded { get; init; }
    public int Attempted { get; init; }
    public RenameBatch? Batch { get; init; }
    public string? Error { get; init; }
    public bool RolledBack { get; init; }
    public bool IsSuccess => Error is null;
}

/// <summary>
/// Performs the actual renames. Every batch runs in two phases (source -&gt; temp,
/// temp -&gt; target) so that cycles and swaps (a-&gt;b, b-&gt;a) work, and so that a failure
/// halfway through can be rolled back to the exact starting state.
/// </summary>
public static class RenameExecutor
{
    private const string TempPrefix = ".brs-tmp-";

    public static RenameResult Apply(IEnumerable<PlanItem> items)
    {
        var moves = new List<(string From, string To)>();
        foreach (var item in items)
        {
            if (item.Status != PlanStatus.Ok) continue;
            var dir = Path.GetDirectoryName(item.SourcePath);
            if (string.IsNullOrEmpty(dir)) continue;
            moves.Add((item.SourcePath, Path.Combine(dir, item.Proposed)));
        }
        return Execute(moves);
    }

    /// <summary>Reverses a previously applied batch.</summary>
    public static RenameResult Undo(RenameBatch batch)
    {
        var moves = batch.Operations
            .AsEnumerable()
            .Reverse()
            .Select(op => (From: op.To, To: op.From))
            .ToList();
        return Execute(moves);
    }

    private static RenameResult Execute(List<(string From, string To)> moves)
    {
        if (moves.Count == 0)
            return new RenameResult { Succeeded = 0, Attempted = 0, Batch = new RenameBatch() };

        var stamp = Guid.NewGuid().ToString("N")[..8];
        var staged = new List<(string Temp, string Original, string Target)>();

        try
        {
            // Phase 1 — park every source under a unique temporary name.
            for (var i = 0; i < moves.Count; i++)
            {
                var (from, to) = moves[i];
                var dir = Path.GetDirectoryName(from) ?? "";
                var temp = Path.Combine(dir, $"{TempPrefix}{stamp}-{i}");
                File.Move(from, temp);
                staged.Add((temp, from, to));
            }

            // Phase 2 — land every temporary file on its final name.
            for (var i = 0; i < staged.Count; i++)
            {
                var s = staged[i];
                File.Move(s.Temp, s.Target);
                staged[i] = (s.Target, s.Original, s.Target); // mark as landed
            }
        }
        catch (Exception ex)
        {
            var rolledBack = TryRollback(staged);
            return new RenameResult
            {
                Attempted = moves.Count,
                Succeeded = 0,
                Error = ex.Message,
                RolledBack = rolledBack,
            };
        }

        var dirOfFirst = Path.GetDirectoryName(moves[0].From) ?? "";
        var batch = new RenameBatch { Directory = dirOfFirst };
        foreach (var (from, to) in moves)
            batch.Operations.Add(new RenameOperation { From = from, To = to });

        return new RenameResult { Attempted = moves.Count, Succeeded = moves.Count, Batch = batch };
    }

    /// <summary>Best-effort restore of the starting state after a mid-batch failure.</summary>
    private static bool TryRollback(List<(string Temp, string Original, string Target)> staged)
    {
        var clean = true;
        for (var i = staged.Count - 1; i >= 0; i--)
        {
            var s = staged[i];
            try
            {
                if (File.Exists(s.Temp) && !string.Equals(s.Temp, s.Original, StringComparison.Ordinal))
                    File.Move(s.Temp, s.Original);
            }
            catch
            {
                clean = false;
            }
        }
        return clean;
    }
}

