using System.Runtime.InteropServices;

namespace BatchRenameStudio.Cli;

/// <summary>
/// A WinExe has no console of its own. When the process is launched from a shell with its
/// output redirected, the inherited handle already works and must NOT be disturbed; only
/// when there is no usable stdout do we attach to the parent console so a human running
/// <c>--plan</c> by hand still sees the summary line.
/// </summary>
internal static class ConsoleBridge
{
    private const int StdOutputHandle = -11;
    private const int StdErrorHandle = -12;
    private const uint AttachParentProcess = 0xFFFFFFFF;

    [DllImport("kernel32.dll", SetLastError = true)]
    private static extern bool AttachConsole(uint dwProcessId);

    [DllImport("kernel32.dll", SetLastError = true)]
    private static extern IntPtr GetStdHandle(int nStdHandle);

    private static bool IsUsable(IntPtr handle) => handle != IntPtr.Zero && handle != new IntPtr(-1);

    public static void Ensure()
    {
        try
        {
            if (IsUsable(GetStdHandle(StdOutputHandle)) && IsUsable(GetStdHandle(StdErrorHandle)))
                return; // redirected or already inherited — leave it alone

            if (!AttachConsole(AttachParentProcess)) return;

            var stdout = Console.OpenStandardOutput();
            if (stdout != Stream.Null)
                Console.SetOut(new StreamWriter(stdout) { AutoFlush = true });

            var stderr = Console.OpenStandardError();
            if (stderr != Stream.Null)
                Console.SetError(new StreamWriter(stderr) { AutoFlush = true });
        }
        catch
        {
            // No console anywhere: the plan file is still written and the exit code still
            // carries the result, so a missing summary line must never fail the run.
        }
    }
}

