using BatchRenameStudio.Cli;
using BatchRenameStudio.Ui;

namespace BatchRenameStudio;

internal static class Program
{
    [STAThread]
    private static int Main(string[] args)
    {
        if (args.Any(a => string.Equals(a, "--plan", StringComparison.OrdinalIgnoreCase)))
        {
            ConsoleBridge.Ensure();
            return PlanCommand.Run(args);
        }

        if (args.Any(a => a is "--help" or "-h" or "/?" or "--version"))
        {
            ConsoleBridge.Ensure();
            Console.Out.WriteLine(PlanCommand.Usage);
            return 0;
        }

        ApplicationConfiguration.Initialize();

        var initialFolder = args.FirstOrDefault(a => !a.StartsWith('-') && Directory.Exists(a));
        Application.Run(new MainForm(initialFolder));
        return 0;
    }
}

