    private readonly TextBox _pattern = new() { Width = 280 };
    private readonly NumericUpDown _start = new() { Minimum = -1000000, Maximum = 1000000, Width = 100 };
    private readonly NumericUpDown _step = new() { Minimum = -100000, Maximum = 100000, Width = 100 };
    private readonly ComboBox _seqPos = new() { DropDownStyle = ComboBoxStyle.DropDownList, Width = 160 };

    // case / extension
    private readonly ComboBox _caseMode = new() { DropDownStyle = ComboBoxStyle.DropDownList, Width = 160 };
    private readonly ComboBox _extMode = new() { DropDownStyle = ComboBoxStyle.DropDownList, Width = 160 };
    private readonly TextBox _extValue = new() { Width = 160 };

    private readonly Label _hint = new()
    {
        AutoSize = false,
        Height = 40,
        Dock = DockStyle.Top,
        ForeColor = SystemColors.GrayText,
        Padding = new Padding(2, 4, 2, 0),
    };

    public RuleStep Step { get; private set; }

    public StepEditorForm(RuleStep? step)
    {
        Step = step?.Clone() ?? new RuleStep { Op = Ops.Replace };

        Text = step is null ? "新增步驟" : "編輯步驟";
        StartPosition = FormStartPosition.CenterParent;
        FormBorderStyle = FormBorderStyle.FixedDialog;
        MinimizeBox = false;
        MaximizeBox = false;
        AutoScaleMode = AutoScaleMode.Dpi;
        ClientSize = new Size(520, 340);
        Padding = new Padding(14);

        _opBox.Items.AddRange(new object[]
        {
            new OpChoice(Ops.Replace, "取代 (replace)"),
            new OpChoice(Ops.Insert, "插入 (insert)"),
            new OpChoice(Ops.Remove, "移除 (remove)"),
            new OpChoice(Ops.Sequence, "編號 (sequence)"),
            new OpChoice(Ops.Case, "大小寫 (case)"),
            new OpChoice(Ops.Extension, "副檔名 (extension)"),
        });

        _insertPos.Items.AddRange(new object[]
        {
            new OpChoice("prefix", "開頭 (prefix)"),
            new OpChoice("suffix", "結尾 (suffix)"),
            new OpChoice("index", "指定位置 (index)"),
        });
        _seqPos.Items.AddRange(new object[]
        {
            new OpChoice("prefix", "開頭 (prefix)"),
