        var cancel = new Button { Text = "取消", DialogResult = DialogResult.Cancel, Width = 92, Height = 30 };
        ok.Click += (_, _) => SaveToStep();

        var buttons = new FlowLayoutPanel
        {
            Dock = DockStyle.Bottom,
            FlowDirection = FlowDirection.RightToLeft,
            Height = 42,
            Padding = new Padding(0, 6, 0, 0),
        };
        buttons.Controls.Add(cancel);
        buttons.Controls.Add(ok);

        var top = new FlowLayoutPanel { Dock = DockStyle.Top, Height = 34, AutoSize = false };
        top.Controls.Add(new Label { Text = "操作：", AutoSize = true, Padding = new Padding(0, 6, 4, 0) });
        top.Controls.Add(_opBox);

        var host = new Panel { Dock = DockStyle.Fill, AutoScroll = true };
        host.Controls.Add(_fields);

        Controls.Add(host);
        Controls.Add(_hint);
        Controls.Add(top);
        Controls.Add(buttons);

        AcceptButton = ok;
        CancelButton = cancel;

        BuildFields();
        UpdateEnabled();
    }

    private string CurrentOp => (_opBox.SelectedItem as OpChoice)?.Value ?? Ops.Replace;

    private void BuildFields()
    {
        _fields.SuspendLayout();
        _fields.Controls.Clear();
        _fields.RowStyles.Clear();
        _fields.RowCount = 0;

        switch (CurrentOp)
        {
            case Ops.Replace:
                AddRow("尋找：", _find);
                AddRow("取代為：", _replaceWith);
                AddRow("", _regex);
                AddRow("", _ignoreCase);
