                AddRow("起始位置：", _from);
                AddRow("字元數：", _count);
                _hint.Text = "起始位置 0 起算；超出長度時自動夾住，不會出錯。";
                break;
            case Ops.Sequence:
                AddRow("樣式：", _pattern);
                AddRow("起始值：", _start);
                AddRow("遞增：", _step);
                AddRow("位置：", _seqPos);
                _hint.Text = "樣式中的 {n:000} 會展開為補零編號（000 代表寬度 3）。計數依處理順序遞增，跳過的檔案也會佔號。";
                break;
            case Ops.Case:
                AddRow("模式：", _caseMode);
                _hint.Text = "title：每一段連續字母的第一個字轉大寫、其餘轉小寫，非字母不動。";
                break;
            case Ops.Extension:
                AddRow("模式：", _extMode);
                AddRow("設定值：", _extValue);
                _hint.Text = "永遠只作用在副檔名上（不含點）。set 可讓沒有副檔名的檔案獲得副檔名。";
                break;
        }

        _fields.ResumeLayout();
    }

