    {
        _fields.RowCount++;
        _fields.RowStyles.Add(new RowStyle(SizeType.AutoSize));
        var lbl = new Label
        {
            Text = label,
            AutoSize = true,
            Anchor = AnchorStyles.Left,
            Padding = new Padding(0, 6, 6, 0),
            Width = 90,
        };
        control.Margin = new Padding(0, 3, 0, 3);
        _fields.Controls.Add(lbl, 0, _fields.RowCount - 1);
        _fields.Controls.Add(control, 1, _fields.RowCount - 1);
    }

    private void UpdateEnabled()
    {
        _index.Enabled = (_insertPos.SelectedItem as OpChoice)?.Value == "index";
        _extValue.Enabled = (_extMode.SelectedItem as OpChoice)?.Value == "set";
    }

    private void LoadFromStep()
    {
        Select(_opBox, Step.Op);
        _find.Text = Step.Find ?? "";
        _replaceWith.Text = Step.ReplaceWith ?? "";
        _regex.Checked = Step.Regex == true;
        _ignoreCase.Checked = Step.IgnoreCase == true;

        _text.Text = Step.Text ?? "";
        Select(_insertPos, Step.Op == Ops.Insert ? Step.Position ?? "prefix" : "prefix");
        _index.Value = Clamp(_index, Step.Index ?? 0);

        _from.Value = Clamp(_from, Step.From ?? 0);
        _count.Value = Clamp(_count, Step.Count ?? 1);

        _pattern.Text = Step.Pattern ?? "{n:000}_";
        _start.Value = Clamp(_start, Step.Start ?? 1);
        _step.Value = Clamp(_step, Step.Step ?? 1);
        Select(_seqPos, Step.Op == Ops.Sequence ? Step.Position ?? "prefix" : "prefix");

        Select(_caseMode, Step.Op == Ops.Case ? Step.Mode ?? "lower" : "lower");
        Select(_extMode, Step.Op == Ops.Extension ? Step.Mode ?? "lower" : "lower");
        _extValue.Text = Step.Value ?? "";
    }

    /// <summary>Writes back only the fields the chosen operation actually owns, so a saved
    /// rules.json never carries leftovers from another op type.</summary>
    private void SaveToStep()
    {
        var s = new RuleStep { Op = CurrentOp };
        switch (s.Op)
        {
            case Ops.Replace:
                s.Find = _find.Text;
                s.ReplaceWith = _replaceWith.Text;
                s.Regex = _regex.Checked;
                s.IgnoreCase = _ignoreCase.Checked;
                break;
            case Ops.Insert:
                s.Text = _text.Text;
                s.Position = (_insertPos.SelectedItem as OpChoice)?.Value ?? "prefix";
                if (s.Position == "index") s.Index = (int)_index.Value;
                break;
            case Ops.Remove:
                s.From = (int)_from.Value;
                s.Count = (int)_count.Value;
                break;
            case Ops.Sequence:
                s.Pattern = _pattern.Text;
                s.Start = (int)_start.Value;
                s.Step = (int)_step.Value;
                s.Position = (_seqPos.SelectedItem as OpChoice)?.Value ?? "prefix";
                break;
            case Ops.Case:
                s.Mode = (_caseMode.SelectedItem as OpChoice)?.Value ?? "lower";
                break;
            case Ops.Extension:
                s.Mode = (_extMode.SelectedItem as OpChoice)?.Value ?? "lower";
                if (s.Mode == "set") s.Value = _extValue.Text;
                break;
        }
        Step = s;
    }

    private static decimal Clamp(NumericUpDown box, int value)
        => Math.Clamp(value, box.Minimum, box.Maximum);

    private static void Select(ComboBox box, string value)
    {
        for (var i = 0; i < box.Items.Count; i++)
        {
            if (box.Items[i] is OpChoice c && c.Value == value) { box.SelectedIndex = i; return; }
        }
        if (box.Items.Count > 0) box.SelectedIndex = 0;
    }

    private sealed class OpChoice(string value, string label)
    {
        public string Value { get; } = value;
        public override string ToString() => label;
    }
}

