using BatchRenameStudio.Core;

namespace BatchRenameStudio.Ui;

/// <summary>
/// The whole GUI: folder picker + rule list on the left, live preview on the right,
/// apply / undo along the bottom. The preview is produced by the very same
/// <see cref="RenameEngine"/> the headless <c>--plan</c> mode uses, so what a human sees
/// is exactly what the plan file would contain.
/// </summary>
internal sealed class MainForm : Form
{
    private readonly TextBox _folderBox = new() { Dock = DockStyle.Fill, ReadOnly = true };
    private readonly ComboBox _applyToBox = new() { DropDownStyle = ComboBoxStyle.DropDownList, Width = 230 };
    private readonly ComboBox _sortBox = new() { DropDownStyle = ComboBoxStyle.DropDownList, Width = 190 };

    private readonly ListView _rulesView = new()
    {
        Dock = DockStyle.Fill,
        View = View.Details,
        FullRowSelect = true,
        HideSelection = false,
        MultiSelect = false,
    };

    private readonly ListView _previewView = new()
    {
        Dock = DockStyle.Fill,
        View = View.Details,
        FullRowSelect = true,
        GridLines = true,
        HideSelection = false,
    };

    private readonly Label _summaryLabel = new()
    {
        Dock = DockStyle.Fill,
        TextAlign = ContentAlignment.MiddleLeft,
        Padding = new Padding(6, 0, 0, 0),
    };

    private readonly Button _applyButton = new() { Text = "套用更名 (&A)", Width = 130, Height = 32 };
    private readonly Button _undoButton = new() { Text = "復原上一批 (&U)", Width = 130, Height = 32, Enabled = false };

    private readonly RuleSet _rules = new();
    private readonly Stack<RenameBatch> _undoStack = new();
    private PlanDocument _plan = new();
    private string _folder = "";

    private static readonly Color OkColor = Color.FromArgb(0, 110, 40);
    private static readonly Color CollisionColor = Color.FromArgb(190, 30, 30);
    private static readonly Color InvalidColor = Color.FromArgb(150, 60, 0);
    private static readonly Color UnchangedColor = SystemColors.GrayText;

    public MainForm(string? initialFolder)
    {
        Text = "Batch Rename Studio";
        AutoScaleMode = AutoScaleMode.Dpi;
        ClientSize = new Size(1120, 660);
        MinimumSize = new Size(900, 520);
        StartPosition = FormStartPosition.CenterScreen;
        AllowDrop = true;

        BuildLayout();
        WireEvents();

        if (!string.IsNullOrEmpty(initialFolder)) SetFolder(initialFolder);
        RefreshRulesView();
        RefreshPreview();
    }

    // ---------------------------------------------------------------- layout

    private void BuildLayout()
    {
        var menu = new MenuStrip();
        var fileMenu = new ToolStripMenuItem("檔案(&F)");
        fileMenu.DropDownItems.Add(NewItem("選擇資料夾…", (_, _) => BrowseFolder()));
        fileMenu.DropDownItems.Add(new ToolStripSeparator());
        fileMenu.DropDownItems.Add(NewItem("載入規則 (rules.json)…", (_, _) => LoadRules()));
        fileMenu.DropDownItems.Add(NewItem("儲存規則 (rules.json)…", (_, _) => SaveRules()));
        fileMenu.DropDownItems.Add(NewItem("匯出計畫 (plan.json)…", (_, _) => ExportPlan()));
        fileMenu.DropDownItems.Add(new ToolStripSeparator());
        fileMenu.DropDownItems.Add(NewItem("結束", (_, _) => Close()));
        var helpMenu = new ToolStripMenuItem("說明(&H)");
        helpMenu.DropDownItems.Add(NewItem("關於 Batch Rename Studio", (_, _) => ShowAbout()));
        menu.Items.Add(fileMenu);
        menu.Items.Add(helpMenu);
        MainMenuStrip = menu;

        // --- header: folder + global options ---
        var header = new TableLayoutPanel
        {
            Dock = DockStyle.Top,
            ColumnCount = 5,
            RowCount = 2,
            Height = 78,
            Padding = new Padding(10, 8, 10, 4),
        };
        header.ColumnStyles.Add(new ColumnStyle(SizeType.AutoSize));
        header.ColumnStyles.Add(new ColumnStyle(SizeType.Percent, 100));
        header.ColumnStyles.Add(new ColumnStyle(SizeType.AutoSize));
        header.ColumnStyles.Add(new ColumnStyle(SizeType.AutoSize));
        header.ColumnStyles.Add(new ColumnStyle(SizeType.AutoSize));

        var browse = new Button { Text = "瀏覽…", Width = 84, Height = 26 };
        browse.Click += (_, _) => BrowseFolder();
        var reload = new Button { Text = "重新整理", Width = 84, Height = 26 };
        reload.Click += (_, _) => RefreshPreview();

        header.Controls.Add(new Label { Text = "資料夾：", AutoSize = true, Anchor = AnchorStyles.Left, Padding = new Padding(0, 5, 4, 0) }, 0, 0);
        header.Controls.Add(_folderBox, 1, 0);
        header.Controls.Add(browse, 2, 0);
        header.Controls.Add(reload, 3, 0);

        _applyToBox.Items.AddRange(new object[]
        {
            new Choice(ApplyTargets.Name, "只改主檔名 (name)"),
            new Choice(ApplyTargets.NameAndExtension, "含副檔名 (nameAndExtension)"),
        });
        _applyToBox.SelectedIndex = 0;

        _sortBox.Items.AddRange(new object[]
        {
            new Choice(SortModes.Name, "檔名 (name)"),
            new Choice(SortModes.Created, "建立時間 (created)"),
            new Choice(SortModes.Modified, "修改時間 (modified)"),
        });
        _sortBox.SelectedIndex = 0;

        var options = new FlowLayoutPanel { Dock = DockStyle.Fill, Height = 32, AutoSize = false };
        options.Controls.Add(new Label { Text = "套用範圍：", AutoSize = true, Padding = new Padding(0, 6, 2, 0) });
        options.Controls.Add(_applyToBox);
        options.Controls.Add(new Label { Text = "處理順序：", AutoSize = true, Padding = new Padding(18, 6, 2, 0) });
        options.Controls.Add(_sortBox);
        header.Controls.Add(options, 1, 1);
        header.SetColumnSpan(options, 4);

        // --- rules panel ---
        var rulesTools = new ToolStrip { GripStyle = ToolStripGripStyle.Hidden };
        var addButton = new ToolStripDropDownButton("新增步驟");
        foreach (var (op, label) in new[]
                 {
                     (Ops.Replace, "取代 (replace)"),
                     (Ops.Insert, "插入 (insert)"),
                     (Ops.Remove, "移除 (remove)"),
                     (Ops.Sequence, "編號 (sequence)"),
                     (Ops.Case, "大小寫 (case)"),
                     (Ops.Extension, "副檔名 (extension)"),
                 })
        {
            var captured = op;
            addButton.DropDownItems.Add(label, null, (_, _) => AddStep(captured));
        }
        rulesTools.Items.Add(addButton);
        rulesTools.Items.Add(new ToolStripSeparator());
        rulesTools.Items.Add(NewToolItem("編輯", (_, _) => EditSelectedStep()));
        rulesTools.Items.Add(NewToolItem("刪除", (_, _) => DeleteSelectedStep()));
        rulesTools.Items.Add(NewToolItem("上移", (_, _) => MoveSelectedStep(-1)));
        rulesTools.Items.Add(NewToolItem("下移", (_, _) => MoveSelectedStep(+1)));
        rulesTools.Items.Add(new ToolStripSeparator());
        rulesTools.Items.Add(NewToolItem("清空", (_, _) => ClearSteps()));

        _rulesView.Columns.Add("#", 34);
        _rulesView.Columns.Add("步驟（由上而下依序套用）", 380);

        var rulesPanel = new Panel { Dock = DockStyle.Fill };
        rulesPanel.Controls.Add(_rulesView);
        rulesPanel.Controls.Add(rulesTools);

        // --- preview panel ---
        _previewView.Columns.Add("原檔名", 260);
        _previewView.Columns.Add("新檔名", 260);
        _previewView.Columns.Add("狀態", 90);
        _previewView.Columns.Add("說明", 200);

        var previewHeader = new Label
        {
            Dock = DockStyle.Top,
            Height = 26,
            Text = "  預覽（與 --plan 產生的結果完全一致）",
            TextAlign = ContentAlignment.MiddleLeft,
            Font = new Font(Font, FontStyle.Bold),
        };
        var previewPanel = new Panel { Dock = DockStyle.Fill };
        previewPanel.Controls.Add(_previewView);
        previewPanel.Controls.Add(previewHeader);

        var split = new SplitContainer
        {
            Dock = DockStyle.Fill,
            SplitterDistance = 430,
            SplitterWidth = 6,
        };
        split.Panel1.Controls.Add(rulesPanel);
        split.Panel2.Controls.Add(previewPanel);

        // --- footer ---
        var footer = new TableLayoutPanel
        {
            Dock = DockStyle.Bottom,
            Height = 48,
            ColumnCount = 3,
            Padding = new Padding(10, 8, 10, 8),
        };
        footer.ColumnStyles.Add(new ColumnStyle(SizeType.Percent, 100));
        footer.ColumnStyles.Add(new ColumnStyle(SizeType.AutoSize));
        footer.ColumnStyles.Add(new ColumnStyle(SizeType.AutoSize));
        footer.Controls.Add(_summaryLabel, 0, 0);
        footer.Controls.Add(_undoButton, 1, 0);
        footer.Controls.Add(_applyButton, 2, 0);

        Controls.Add(split);
        Controls.Add(footer);
        Controls.Add(header);
        Controls.Add(menu);
    }

    private void WireEvents()
    {
        _applyToBox.SelectedIndexChanged += (_, _) =>
        {
            _rules.ApplyTo = ((Choice)_applyToBox.SelectedItem!).Value;
            RefreshPreview();
        };
        _sortBox.SelectedIndexChanged += (_, _) =>
        {
            _rules.Sort = ((Choice)_sortBox.SelectedItem!).Value;
            RefreshPreview();
        };
        _rulesView.DoubleClick += (_, _) => EditSelectedStep();
        _previewView.DoubleClick += (_, _) => EditSelectedStep();
        _applyButton.Click += (_, _) => ApplyRenames();
        _undoButton.Click += (_, _) => UndoLastBatch();

        DragEnter += (_, e) =>
        {
            if (e.Data?.GetDataPresent(DataFormats.FileDrop) == true)
                e.Effect = DragDropEffects.Copy;
        };
        DragDrop += (_, e) =>
        {
            if (e.Data?.GetData(DataFormats.FileDrop) is string[] paths && paths.Length > 0)
            {
                var path = Directory.Exists(paths[0]) ? paths[0] : Path.GetDirectoryName(paths[0]);
                if (!string.IsNullOrEmpty(path)) SetFolder(path);
            }
        };
    }

    private static ToolStripMenuItem NewItem(string text, EventHandler handler)
    {
        var item = new ToolStripMenuItem(text);
        item.Click += handler;
        return item;
    }

    private static ToolStripButton NewToolItem(string text, EventHandler handler)
    {
        var item = new ToolStripButton(text) { DisplayStyle = ToolStripItemDisplayStyle.Text };
        item.Click += handler;
        return item;
    }

    // ---------------------------------------------------------------- rules

    private void AddStep(string op)
    {
        using var dlg = new StepEditorForm(new RuleStep { Op = op, Pattern = "{n:000}_", Mode = DefaultMode(op) });
        if (dlg.ShowDialog(this) != DialogResult.OK) return;
        _rules.Steps.Add(dlg.Step);
        RefreshRulesView();
        SelectRule(_rules.Steps.Count - 1);
        RefreshPreview();
    }

    private static string? DefaultMode(string op) => op switch
    {
        Ops.Case => "lower",
        Ops.Extension => "lower",
        _ => null,
    };

    private void EditSelectedStep()
    {
        var i = SelectedRuleIndex;
        if (i < 0) return;
        using var dlg = new StepEditorForm(_rules.Steps[i]);
        if (dlg.ShowDialog(this) != DialogResult.OK) return;
        _rules.Steps[i] = dlg.Step;
        RefreshRulesView();
        SelectRule(i);
        RefreshPreview();
    }

    private void DeleteSelectedStep()
    {
        var i = SelectedRuleIndex;
        if (i < 0) return;
        _rules.Steps.RemoveAt(i);
        RefreshRulesView();
        SelectRule(Math.Min(i, _rules.Steps.Count - 1));
        RefreshPreview();
    }

    private void MoveSelectedStep(int delta)
    {
        var i = SelectedRuleIndex;
        var j = i + delta;
        if (i < 0 || j < 0 || j >= _rules.Steps.Count) return;
        (_rules.Steps[i], _rules.Steps[j]) = (_rules.Steps[j], _rules.Steps[i]);
        RefreshRulesView();
        SelectRule(j);
        RefreshPreview();
    }

    private void ClearSteps()
    {
        if (_rules.Steps.Count == 0) return;
        if (MessageBox.Show(this, "確定要清空所有步驟？", "Batch Rename Studio",
                MessageBoxButtons.YesNo, MessageBoxIcon.Question) != DialogResult.Yes) return;
        _rules.Steps.Clear();
        RefreshRulesView();
        RefreshPreview();
    }

    private int SelectedRuleIndex =>
        _rulesView.SelectedIndices.Count > 0 ? _rulesView.SelectedIndices[0] : -1;

    private void SelectRule(int index)
    {
        if (index < 0 || index >= _rulesView.Items.Count) return;
        _rulesView.Items[index].Selected = true;
        _rulesView.Items[index].EnsureVisible();
        _rulesView.Focus();
    }

    private void RefreshRulesView()
    {
        _rulesView.BeginUpdate();
        _rulesView.Items.Clear();
        for (var i = 0; i < _rules.Steps.Count; i++)
        {
            var row = new ListViewItem((i + 1).ToString());
            row.SubItems.Add(_rules.Steps[i].Describe());
            _rulesView.Items.Add(row);
        }
        _rulesView.EndUpdate();
    }

    // ---------------------------------------------------------------- folder & preview

    private void BrowseFolder()
    {
        using var dlg = new FolderBrowserDialog { Description = "選擇要批次更名的資料夾", UseDescriptionForTitle = true };
        if (!string.IsNullOrEmpty(_folder)) dlg.SelectedPath = _folder;
        if (dlg.ShowDialog(this) == DialogResult.OK) SetFolder(dlg.SelectedPath);
    }

    private void SetFolder(string path)
    {
        _folder = path;
        _folderBox.Text = path;
        _undoStack.Clear();
        _undoButton.Enabled = false;
        RefreshPreview();
    }

    private void RefreshPreview()
    {
        _previewView.BeginUpdate();
        _previewView.Items.Clear();

        if (string.IsNullOrEmpty(_folder) || !Directory.Exists(_folder))
        {
            _previewView.EndUpdate();
            _plan = new PlanDocument();
            _summaryLabel.Text = "尚未選擇資料夾。可用「瀏覽…」或直接把資料夾拖進視窗。";
            _applyButton.Enabled = false;
            return;
        }

        try
        {
            _plan = RenameEngine.Plan(_folder, _rules);
        }
        catch (Exception ex)
        {
            _previewView.EndUpdate();
            _plan = new PlanDocument();
            _summaryLabel.Text = "規則有誤：" + ex.Message;
            _summaryLabel.ForeColor = CollisionColor;
            _applyButton.Enabled = false;
            return;
        }

        foreach (var item in _plan.Items)
        {
            var row = new ListViewItem(item.Original);
            row.SubItems.Add(item.Proposed);
            row.SubItems.Add(StatusLabel(item.Status));
            row.SubItems.Add(item.Reason);
            row.ForeColor = item.Status switch
            {
                PlanStatus.Ok => OkColor,
                PlanStatus.Collision => CollisionColor,
                PlanStatus.Invalid => InvalidColor,
                _ => UnchangedColor,
            };
            _previewView.Items.Add(row);
        }
        _previewView.EndUpdate();

        var s = _plan.Summary;
        _summaryLabel.ForeColor = SystemColors.ControlText;
        _summaryLabel.Text = $"共 {s.Total} 個檔案　可更名 {s.Ok}　衝突 {s.Collision}　未變更 {s.Unchanged}　不合法 {s.Invalid}";
        _applyButton.Enabled = s.Ok > 0;
    }

    private static string StatusLabel(string status) => status switch
    {
        PlanStatus.Ok => "可更名",
        PlanStatus.Collision => "衝突",
        PlanStatus.Unchanged => "未變更",
        PlanStatus.Invalid => "不合法",
        _ => status,
    };

    // ---------------------------------------------------------------- apply / undo

    private void ApplyRenames()
    {
        var okCount = _plan.Summary.Ok;
        if (okCount == 0) return;

        var skipped = _plan.Summary.Total - okCount;
        var message = $"即將更名 {okCount} 個檔案。";
        if (skipped > 0) message += $"\n另有 {skipped} 個項目（衝突／未變更／不合法）會被略過。";
        message += "\n\n要繼續嗎？";

        if (MessageBox.Show(this, message, "確認更名", MessageBoxButtons.OKCancel, MessageBoxIcon.Warning)
            != DialogResult.OK) return;

        Cursor = Cursors.WaitCursor;
        RenameResult result;
        try
        {
            result = RenameExecutor.Apply(_plan.Items);
        }
        finally
        {
            Cursor = Cursors.Default;
        }

        if (!result.IsSuccess)
        {
            MessageBox.Show(this,
                $"更名失敗：{result.Error}\n\n{(result.RolledBack ? "已完整還原為原始狀態。" : "自動還原未完全成功，請手動檢查資料夾。")}",
                "Batch Rename Studio", MessageBoxButtons.OK, MessageBoxIcon.Error);
        }
        else if (result.Batch is not null && result.Batch.Operations.Count > 0)
        {
            _undoStack.Push(result.Batch);
            _undoButton.Enabled = true;
            PersistUndoLog(result.Batch);
        }

        RefreshPreview();
    }

    private void UndoLastBatch()
    {
        if (_undoStack.Count == 0) return;
        var batch = _undoStack.Peek();

        if (MessageBox.Show(this, $"要復原上一批 {batch.Operations.Count} 個更名嗎？", "確認復原",
                MessageBoxButtons.OKCancel, MessageBoxIcon.Question) != DialogResult.OK) return;

        var result = RenameExecutor.Undo(batch);
        if (!result.IsSuccess)
        {
            MessageBox.Show(this, "復原失敗：" + result.Error, "Batch Rename Studio",
                MessageBoxButtons.OK, MessageBoxIcon.Error);
        }
        else
        {
            _undoStack.Pop();
            _undoButton.Enabled = _undoStack.Count > 0;
        }
        RefreshPreview();
    }

    /// <summary>Writes the last applied batch to disk so the moves can be reconstructed by
    /// hand even if the app is closed. Failure here must never break a successful rename.</summary>
    private static void PersistUndoLog(RenameBatch batch)
    {
        try
        {
            var dir = Path.Combine(
                Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),
                "BatchRenameStudio");
            Directory.CreateDirectory(dir);
            File.WriteAllText(Path.Combine(dir, "last-batch.json"), batch.ToJson(), Utf8.NoBom);
        }
        catch
        {
            // best effort only
        }
    }

    // ---------------------------------------------------------------- file menu

    private void LoadRules()
    {
        using var dlg = new OpenFileDialog { Filter = "規則檔 (*.json)|*.json|所有檔案 (*.*)|*.*", Title = "載入規則" };
        if (dlg.ShowDialog(this) != DialogResult.OK) return;
        try
        {
            var loaded = RuleSet.Load(dlg.FileName);
            _rules.ApplyTo = loaded.ApplyTo;
            _rules.Sort = loaded.Sort;
            _rules.Steps.Clear();
            _rules.Steps.AddRange(loaded.Steps);
            SelectChoice(_applyToBox, _rules.ApplyTo);
            SelectChoice(_sortBox, _rules.Sort);
            RefreshRulesView();
            RefreshPreview();
        }
        catch (Exception ex)
        {
            MessageBox.Show(this, ex.Message, "載入失敗", MessageBoxButtons.OK, MessageBoxIcon.Error);
        }
    }

    private void SaveRules()
    {
        using var dlg = new SaveFileDialog { Filter = "規則檔 (*.json)|*.json", FileName = "rules.json", Title = "儲存規則" };
        if (dlg.ShowDialog(this) != DialogResult.OK) return;
        try
        {
            _rules.Save(dlg.FileName);
        }
        catch (Exception ex)
        {
            MessageBox.Show(this, ex.Message, "儲存失敗", MessageBoxButtons.OK, MessageBoxIcon.Error);
        }
    }

    private void ExportPlan()
    {
        if (_plan.Items.Count == 0)
        {
            MessageBox.Show(this, "目前沒有可匯出的計畫。", "Batch Rename Studio",
                MessageBoxButtons.OK, MessageBoxIcon.Information);
            return;
        }
        using var dlg = new SaveFileDialog { Filter = "計畫檔 (*.json)|*.json", FileName = "plan.json", Title = "匯出計畫" };
        if (dlg.ShowDialog(this) != DialogResult.OK) return;
        try
        {
            _plan.Save(dlg.FileName);
        }
        catch (Exception ex)
        {
            MessageBox.Show(this, ex.Message, "匯出失敗", MessageBoxButtons.OK, MessageBoxIcon.Error);
        }
    }

    private void ShowAbout()
    {
        MessageBox.Show(this,
            """
            Batch Rename Studio 1.0

            批次更名工具，預覽即計畫：畫面上看到的結果與
            headless 模式產生的 plan.json 完全一致。

            headless 用法：
              BatchRenameStudio.exe --plan --dir <folder> --rules <rules.json> --out <plan.json>
            """,
            "關於", MessageBoxButtons.OK, MessageBoxIcon.Information);
    }

    private static void SelectChoice(ComboBox box, string value)
    {
        for (var i = 0; i < box.Items.Count; i++)
        {
            if (box.Items[i] is Choice c && c.Value == value) { box.SelectedIndex = i; return; }
        }
    }

    private sealed class Choice(string value, string label)
    {
        public string Value { get; } = value;
        public override string ToString() => label;
    }
}

