/// <summary>
/// Runs once the container has its real width. Every value is clamped and the whole
/// thing is guarded, because a cosmetic layout preference must never be able to
/// take the window down.
/// </summary>
private void ConfigureSplitter()
{
    try
    {
        var width = _split.Width;
        if (width < 400) return;

        _split.Panel1MinSize = 240;
        _split.Panel2MinSize = 300;

        var max = width - _split.Panel2MinSize - _split.SplitterWidth;
        if (max <= _split.Panel1MinSize) return;
        _split.SplitterDistance = Math.Clamp(440, _split.Panel1MinSize, max);
    }
    catch (Exception ex) when (ex is InvalidOperationException or ArgumentException)
    {
        // Window too narrow for the preferred split; the default position is fine.
    }
}

