using System.Text.Json;
using BatchRenameStudio.Core;

namespace BatchRenameStudio.Cli;

/// <summary>
/// Optional headless execution verbs, deliberately kept separate from the fixed
/// <c>--plan</c> contract so that planning can never rename anything:
/// <code>
/// BatchRenameStudio.exe --apply --dir &lt;folder&gt; --rules &lt;rules.json&gt; [--undo-log &lt;path&gt;]
/// BatchRenameStudio.exe --undo  --log &lt;undo.json&gt;
/// </code>
/// Only items with status <c>ok</c> are renamed; everything else is reported as skipped.
/// </summary>
internal static class ApplyCommand
{
    public static int RunApply(string[] args)
    {
        string? dir = null, rulesPath = null, undoLog = null;

        for (var i = 0; i < args.Length; i++)
        {
            var (key, inline) = SplitArg(args[i]);
            switch (key)
            {
                case "--apply": break;
                case "--dir": dir = inline ?? Next(args, ref i); break;
                case "--rules": rulesPath = inline ?? Next(args, ref i); break;
                case "--undo-log": undoLog = inline ?? Next(args, ref i); break;
                default: return Fail($"未知的參數：{args[i]}");
            }
        }

        if (string.IsNullOrWhiteSpace(dir)) return Fail("缺少 --dir <folder>。");
        if (string.IsNullOrWhiteSpace(rulesPath)) return Fail("缺少 --rules <rules.json>。");

        try
        {
            if (!Directory.Exists(dir)) return Fail($"找不到資料夾：{dir}");
            if (!File.Exists(rulesPath)) return Fail($"找不到規則檔：{rulesPath}");

            var plan = RenameEngine.Plan(dir, RuleSet.Load(rulesPath));
            var result = RenameExecutor.Apply(plan.Items);

            if (!result.IsSuccess)
                return Fail($"更名失敗：{result.Error}（{(result.RolledBack ? "已還原" : "還原未完全，請手動檢查")}）");

            if (!string.IsNullOrWhiteSpace(undoLog) && result.Batch is not null)
            {
                var full = Path.GetFullPath(undoLog);
                var parent = Path.GetDirectoryName(full);
                if (!string.IsNullOrEmpty(parent)) Directory.CreateDirectory(parent);
                File.WriteAllText(full, result.Batch.ToJson(), Utf8.NoBom);
            }

            Console.Out.WriteLine($"apply: renamed={result.Succeeded} skipped={plan.Summary.Total - result.Succeeded}");
            Console.Out.Flush();
            return PlanCommand.ExitOk;
        }
        catch (RuleSetException ex)
        {
            return Fail(ex.Message);
        }
        catch (Exception ex)
        {
            return Fail($"{ex.GetType().Name}: {ex.Message}");
        }
    }

    public static int RunUndo(string[] args)
    {
        string? logPath = null;
        for (var i = 0; i < args.Length; i++)
        {
            var (key, inline) = SplitArg(args[i]);
            switch (key)
            {
                case "--undo": break;
                case "--log": logPath = inline ?? Next(args, ref i); break;
                default: return Fail($"未知的參數：{args[i]}");
            }
        }

        if (string.IsNullOrWhiteSpace(logPath)) return Fail("缺少 --log <undo.json>。");

        try
        {
            if (!File.Exists(logPath)) return Fail($"找不到復原記錄：{logPath}");

            var batch = JsonSerializer.Deserialize<RenameBatch>(File.ReadAllText(logPath))
                        ?? throw new RuleSetException("復原記錄內容為空。");

            var result = RenameExecutor.Undo(batch);
            if (!result.IsSuccess) return Fail($"復原失敗：{result.Error}");

            Console.Out.WriteLine($"undo: restored={result.Succeeded}");
            Console.Out.Flush();
            return PlanCommand.ExitOk;
        }
        catch (Exception ex)
        {
            return Fail($"{ex.GetType().Name}: {ex.Message}");
        }
    }

    private static (string Key, string? Value) SplitArg(string arg)
    {
        var eq = arg.IndexOf('=');
        return eq > 0 ? (arg[..eq], arg[(eq + 1)..]) : (arg, null);
    }

    private static string? Next(string[] args, ref int i) => i + 1 < args.Length ? args[++i] : null;

    private static int Fail(string message)
    {
        Console.Error.WriteLine("error: " + message);
        Console.Error.Flush();
        return PlanCommand.ExitError;
    }
}

