using BatchRenameStudio.Core;

namespace BatchRenameStudio.Cli;

/// <summary>
/// Headless planning mode:
/// <code>BatchRenameStudio.exe --plan --dir &lt;folder&gt; --rules &lt;rules.json&gt; --out &lt;plan.json&gt;</code>
/// Exit 0 on success, 2 on any error. Nothing but one summary line ever reaches stdout;
/// diagnostics go to stderr. This mode never renames anything.
/// </summary>
internal static class PlanCommand
{
    public const int ExitOk = 0;
    public const int ExitError = 2;

    public static int Run(string[] args)
    {
        string? dir = null, rulesPath = null, outPath = null;

        for (var i = 0; i < args.Length; i++)
        {
            var (key, inlineValue) = SplitArg(args[i]);
            switch (key)
            {
                case "--plan":
                    break;
                case "--dir":
                    dir = inlineValue ?? Next(args, ref i);
                    break;
                case "--rules":
                    rulesPath = inlineValue ?? Next(args, ref i);
                    break;
                case "--out":
                    outPath = inlineValue ?? Next(args, ref i);
                    break;
                default:
                    return Fail($"未知的參數：{args[i]}");
            }
        }

        if (string.IsNullOrWhiteSpace(dir)) return Fail("缺少 --dir <folder>。");
        if (string.IsNullOrWhiteSpace(rulesPath)) return Fail("缺少 --rules <rules.json>。");
        if (string.IsNullOrWhiteSpace(outPath)) return Fail("缺少 --out <plan.json>。");

        try
        {
            if (!Directory.Exists(dir)) return Fail($"找不到資料夾：{dir}");
            if (!File.Exists(rulesPath)) return Fail($"找不到規則檔：{rulesPath}");

            var rules = RuleSet.Load(rulesPath);
            var plan = RenameEngine.Plan(dir, rules);
            plan.Save(outPath);

            // The single permitted stdout line. ASCII only, so no console code page can mangle it.
            Console.Out.WriteLine($"plan: {plan.Summary}");
            Console.Out.Flush();
            return ExitOk;
        }
        catch (RuleSetException ex)
        {
            return Fail(ex.Message);
        }
        catch (Exception ex)
        {
            return Fail($"{ex.GetType().Name}: {ex.Message}");
        }
    }

    private static (string Key, string? Value) SplitArg(string arg)
    {
        var eq = arg.IndexOf('=');
        return eq > 0 ? (arg[..eq], arg[(eq + 1)..]) : (arg, null);
    }

    private static string? Next(string[] args, ref int i)
        => i + 1 < args.Length ? args[++i] : null;

    private static int Fail(string message)
    {
        Console.Error.WriteLine("error: " + message);
        Console.Error.Flush();
        return ExitError;
    }

    public static string Usage =>
        """
        Batch Rename Studio

          BatchRenameStudio.exe                       啟動圖形介面
          BatchRenameStudio.exe <folder>              啟動圖形介面並載入資料夾
          BatchRenameStudio.exe --plan --dir <folder> --rules <rules.json> --out <plan.json>
                                                      產生更名計畫（不會實際更名），成功時 exit 0
        """;
}

